/**
 * Rebuilds db/schema.sql (a read-only, all-in-one view for reviewing) from db/migrations.
 * The migrations are the source of truth; never edit schema.sql by hand.
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const dir = join(process.cwd(), 'db', 'migrations');
const files = readdirSync(dir).filter((f) => /^\d{4}_.+\.sql$/.test(f)).sort();
const banner = `-- =====================================================================
-- GENERATED by "npm run db:schema" from db/migrations. Do not edit.
-- This file is for reading the whole schema in one place.
-- =====================================================================
`;
const body = files.map((f) => `-- >>> ${f}\n${readFileSync(join(dir, f), 'utf8').trimEnd()}\n`).join('\n\n');
writeFileSync(join(process.cwd(), 'db', 'schema.sql'), `${banner}\n${body}`);
console.log(`db/schema.sql rebuilt from ${files.length} migrations.`);
